<?php
declare(strict_types=1);

namespace Surfnet\StepupGateway\Tests\Functional\Support\Saml;

/**
 * Loads SAML fixtures from PHP files. Each fixture is a PHP file that returns a string (the SAML message).
 *
 * The messages captured from devconf are in Fixtures/devconf/saml/, the baselines of the responses of the Gateway
 * (generated by the tests) in Fixtures/saml/baselines/.
 */
class SamlFixtureLoader
{
    private string $capturedPath;
    private string $baselinesPath;

    public function __construct(string $fixturesPath)
    {
        $this->capturedPath = $fixturesPath . '/devconf/saml';
        $this->baselinesPath = $fixturesPath . '/saml/baselines';
    }

    /**
     * Load a pre-signed HTTP-Redirect AuthnRequest query string.
     *
     * @param string $name Fixture name (e.g., 'sfo-redirect-joe-a-yk-loa2')
     */
    public function loadRedirectAuthnRequest(string $name): string
    {
        return $this->loadFixture($this->capturedPath . '/authn-requests/' . $name);
    }

    /**
     * Load a pre-signed HTTP-POST AuthnRequest (base64-encoded XML).
     */
    public function loadPostAuthnRequest(string $name): string
    {
        return $this->loadFixture($this->capturedPath . '/authn-requests/' . $name);
    }

    /**
     * Load a pre-signed HTTP-POST Response (base64-encoded XML).
     */
    public function loadPostResponse(string $name): string
    {
        return $this->loadFixture($this->capturedPath . '/responses/' . $name);
    }

    /**
     * Load the baseline of a Response of the Gateway (base64-encoded XML), generated with UPDATE_SAML_BASELINES=1.
     */
    public function loadBaselineResponse(string $name): string
    {
        return $this->loadFixture($this->baselinesPath . '/' . $name);
    }

    /**
     * Load a PHP fixture file (without the .php extension) that returns a string.
     */
    private function loadFixture(string $path): string
    {
        $file = $path . '.php';
        if (!file_exists($file)) {
            throw new \RuntimeException(sprintf('SAML fixture not found: %s', $file));
        }

        $result = require $file;
        if (!is_string($result)) {
            throw new \RuntimeException(sprintf(
                'SAML fixture %s must return a string, got %s',
                $file,
                gettype($result)
            ));
        }

        return $result;
    }
}
